package com.cityhealthcare.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="doctor_reviews") public class DoctorReview { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="patient_id") private Account patient; @ManyToOne(optional=false) @JoinColumn(name="doctor_id") private Account doctor; @Column(nullable=false) private int rating; @Column(nullable=false,length=1500) private String review; private LocalDateTime createdAt=LocalDateTime.now(); public DoctorReview(){} public DoctorReview(Account p,Account d,int r,String t){patient=p;doctor=d;rating=r;review=t;} public Long getId(){return id;} public Account getPatient(){return patient;} public Account getDoctor(){return doctor;} public int getRating(){return rating;} public String getReview(){return review;} public LocalDateTime getCreatedAt(){return createdAt;} }